#include <iostream>
using namespace std;

int main() {
    int a[2][3] = {{1, 2, 3}, {4, 5, 6}};  // a = 两行三列的数组
    int s = 0;  // s = 总和
    for (int i = 0; i < 2; i++) {  // i = 行下标
        for (int j = 0; j < 3; j++) {  // j = 列下标
            s += a[i][j];
        }
    }
    cout << s << endl;
    return 0;
}
